--- /dev/null
+++ b/docs_cmd.go
@@ -0,0 +1,52 @@
+package main
+
+import (
+	"errors"
+	"flag"
+	"fmt"
+	"io"
+	"os"
+
+	"px1/internal/docs"
+)
+
+// runDocs is "px1 docs <check|manifest>": the documentation's own checks.
+func runDocs(args []string, stdout io.Writer) error {
+	if len(args) == 0 {
+		return errors.New("usage: px1 docs <check|manifest> [--root dir]")
+	}
+	fs := flag.NewFlagSet("docs "+args[0], flag.ContinueOnError)
+	fs.SetOutput(os.Stderr)
+	root := fs.String("root", ".", "repository root")
+	if err := fs.Parse(args[1:]); err != nil {
+		return err
+	}
+	switch args[0] {
+	case "check":
+		problems, err := docs.Check(*root)
+		if err != nil {
+			return err
+		}
+		for _, problem := range problems {
+			fmt.Fprintln(stdout, problem)
+		}
+		if len(problems) > 0 {
+			return fmt.Errorf("docs check found %d problem(s)", len(problems))
+		}
+		fmt.Fprintln(stdout, "docs check: ok")
+		return nil
+	case "manifest":
+		changed, err := docs.WriteGenerated(*root)
+		if err != nil {
+			return err
+		}
+		for _, rel := range changed {
+			fmt.Fprintln(stdout, "wrote", rel)
+		}
+		if len(changed) == 0 {
+			fmt.Fprintln(stdout, "docs manifest: up to date")
+		}
+		return nil
+	}
+	return fmt.Errorf("unknown docs command %q: use check or manifest", args[0])
+}

diff --git a/internal/docs/check.go b/internal/docs/check.go
new file mode 100644
index 0000000..fa6f55d
--- /dev/null
+++ b/internal/docs/check.go
@@ -0,0 +1,264 @@
+package docs
+
+import (
+	"bytes"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"io/fs"
+	"os"
+	"path"
+	"path/filepath"
+	"regexp"
+	"sort"
+	"strings"
+)
+
+// ConfigFile holds what the checks cannot derive: code that is knowingly
+// undocumented, and non-Go paths that need a page.
+const ConfigFile = Dir + "/docs.config.json"
+
+// Config is docs/docs.config.json.
+type Config struct {
+	// KnownGaps are code units with no page yet. The check fails when new
+	// code has no page and is not listed here, and when a listed gap has
+	// been closed or removed, so the list can only shrink honestly.
+	KnownGaps []string `json:"known_gaps"`
+	// ExtraUnits are paths outside Go packages that need a page, such as an
+	// action definition or the dashboard.
+	ExtraUnits []string `json:"extra_units"`
+	// Exclude are directories that are not px1 code.
+	Exclude []string `json:"exclude"`
+}
+
+// LoadConfig reads the config. A missing file is an empty config.
+func LoadConfig(root string) (Config, error) {
+	var cfg Config
+	data, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(ConfigFile)))
+	if errors.Is(err, fs.ErrNotExist) {
+		return cfg, nil
+	}
+	if err != nil {
+		return cfg, err
+	}
+	// A misspelt key would silently drop the units it was meant to add.
+	dec := json.NewDecoder(bytes.NewReader(data))
+	dec.DisallowUnknownFields()
+	if err := dec.Decode(&cfg); err != nil {
+		return cfg, fmt.Errorf("%s: %w", ConfigFile, err)
+	}
+	return cfg, nil
+}
+
+// Check runs every check and returns the problems sorted by path and line.
+func Check(root string) ([]Problem, error) {
+	cfg, err := LoadConfig(root)
+	if err != nil {
+		return nil, err
+	}
+	pages, problems, err := LoadPages(root)
+	if err != nil {
+		return nil, err
+	}
+	for _, page := range pages {
+		problems = append(problems, checkLinks(root, page)...)
+		problems = append(problems, checkCovers(root, page)...)
+	}
+	units, err := CodeUnits(root, cfg)
+	if err != nil {
+		return nil, err
+	}
+	problems = append(problems, checkCoverage(root, pages, units, cfg)...)
+	problems = append(problems, checkGenerated(root, pages)...)
+	sort.SliceStable(problems, func(i, j int) bool {
+		if problems[i].Path != problems[j].Path {
+			return problems[i].Path < problems[j].Path
+		}
+		return problems[i].Line < problems[j].Line
+	})
+	return problems, nil
+}
+
+var linkRE = regexp.MustCompile(`\]\(([^)\s]+)(?:\s+"[^"]*")?\)`)
+
+// checkLinks reports relative links that do not resolve to a file in the
+// repository. Links inside fenced code are examples, not links.
+func checkLinks(root string, page Page) []Problem {
+	var problems []Problem
+	inFence := false
+	for i, line := range strings.Split(page.body, "\n") {
+		if strings.HasPrefix(strings.TrimSpace(line), "```") {
+			inFence = !inFence
+			continue
+		}
+		if inFence {
+			continue
+		}
+		for _, m := range linkRE.FindAllStringSubmatch(line, -1) {
+			target := m[1]
+			if strings.Contains(target, "://") || strings.HasPrefix(target, "mailto:") || strings.HasPrefix(target, "#") {
+				continue
+			}
+			target, _, _ = strings.Cut(target, "#")
+			var rel string
+			if strings.HasPrefix(target, "/") {
+				rel = strings.TrimPrefix(target, "/")
+			} else {
+				rel = path.Join(path.Dir(page.Path), target)
+			}
+			if rel == ".." || strings.HasPrefix(rel, "../") {
+				problems = append(problems, Problem{page.Path, page.bodyStart + i, "link leaves the repository: " + m[1]})
+				continue
+			}
+			if _, err := os.Stat(filepath.Join(root, filepath.FromSlash(rel))); err != nil {
+				problems = append(problems, Problem{page.Path, page.bodyStart + i, "broken link: " + m[1]})
+			}
+		}
+	}
+	return problems
+}
+
+// checkCovers reports covers entries that name nothing in the repository.
+func checkCovers(root string, page Page) []Problem {
+	var problems []Problem
+	for _, entry := range page.Covers {
+		if entry == "" || strings.HasPrefix(entry, "/") || strings.Contains(entry, "..") {
+			problems = append(problems, Problem{page.Path, 1, fmt.Sprintf("covers entry %q must be a path inside the repository", entry)})
+			continue
+		}
+		if strings.ContainsAny(entry, "*?[") {
+			matches, err := filepath.Glob(filepath.Join(root, filepath.FromSlash(entry)))
+			if err != nil || len(matches) == 0 {
+				problems = append(problems, Problem{page.Path, 1, "covers pattern matches nothing: " + entry})
+			}
+			continue
+		}
+		info, err := os.Stat(filepath.Join(root, filepath.FromSlash(entry)))
+		switch {
+		case err != nil:
+			problems = append(problems, Problem{page.Path, 1, "covers a path that does not exist: " + entry})
+		case info.IsDir() != strings.HasSuffix(entry, "/"):
+			problems = append(problems, Problem{page.Path, 1, "covers entry must end in / exactly when it is a directory: " + entry})
+		}
+	}
+	return problems
+}
+
+// CodeUnits lists what needs documentation: every Go package directory (as
+// "dir/"), every non-test Go file of the root package (one command each, more
+// or less), and the config's extra units.
+func CodeUnits(root string, cfg Config) ([]string, error) {
+	skip := map[string]bool{Dir: true, "node_modules": true, "testdata": true, "vendor": true}
+	for _, dir := range cfg.Exclude {
+		skip[strings.TrimSuffix(dir, "/")] = true
+	}
+	set := map[string]bool{}
+	err := filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
+		if err != nil {
+			return err
+		}
+		rel, _ := filepath.Rel(root, p)
+		rel = filepath.ToSlash(rel)
+		if d.IsDir() {
+			if rel != "." && (strings.HasPrefix(d.Name(), ".") || skip[d.Name()] || skip[rel]) {
+				return filepath.SkipDir
+			}
+			return nil
+		}
+		if !strings.HasSuffix(rel, ".go") || strings.HasSuffix(rel, "_test.go") {
+			return nil
+		}
+		if dir := path.Dir(rel); dir == "." {
+			set[rel] = true
+		} else {
+			set[dir+"/"] = true
+		}
+		return nil
+	})
+	if err != nil {
+		return nil, err
+	}
+	for _, unit := range cfg.ExtraUnits {
+		set[unit] = true
+	}
+	units := make([]string, 0, len(set))
+	for unit := range set {
+		units = append(units, unit)
+	}
+	sort.Strings(units)
+	return units, nil
+}
+
+// covered reports whether a covers entry describes a unit: the same path, a
+// directory that contains the unit, a path inside the unit, or a glob that
+// matches it.
+func covered(unit, entry string) bool {
+	if unit == entry {
+		return true
+	}
+	if strings.HasSuffix(entry, "/") && strings.HasPrefix(unit, entry) {
+		return true
+	}
+	if strings.HasSuffix(unit, "/") && strings.HasPrefix(entry, unit) {
+		return true
+	}
+	if strings.ContainsAny(entry, "*?[") {
+		if ok, _ := path.Match(entry, unit); ok {
+			return true
+		}
+	}
+	return false
+}
+
+// checkCoverage enforces the gap policy: code needs a page or an entry in
+// known_gaps, and known_gaps holds nothing that is covered or gone.
+func checkCoverage(root string, pages []Page, units []string, cfg Config) []Problem {
+	isCovered := func(unit string) bool {
+		for _, page := range pages {
+			for _, entry := range page.Covers {
+				if covered(unit, entry) {
+					return true
+				}
+			}
+		}
+		return false
+	}
+	known := map[string]bool{}
+	for _, gap := range cfg.KnownGaps {
+		known[gap] = true
+	}
+	isUnit := map[string]bool{}
+	var problems []Problem
+	for _, unit := range units {
+		isUnit[unit] = true
+		if !isCovered(unit) && !known[unit] {
+			problems = append(problems, Problem{ConfigFile, 0, fmt.Sprintf("%s has no page: add it to a page's covers, or to known_gaps", unit)})
+		}
+	}
+	for _, gap := range cfg.KnownGaps {
+		switch {
+		case !isUnit[gap]:
+			problems = append(problems, Problem{ConfigFile, 0, fmt.Sprintf("known gap %s is not a code unit any more: remove it", gap)})
+		case isCovered(gap):
+			problems = append(problems, Problem{ConfigFile, 0, fmt.Sprintf("known gap %s now has a page: remove it", gap)})
+		}
+	}
+	for _, unit := range cfg.ExtraUnits {
+		if _, err := os.Stat(filepath.Join(root, filepath.FromSlash(unit))); err != nil {
+			problems = append(problems, Problem{ConfigFile, 0, "extra unit does not exist: " + unit})
+		}
+	}
+	return problems
+}
+
+// checkGenerated reports a manifest or index that no longer matches the pages.
+func checkGenerated(root string, pages []Page) []Problem {
+	var problems []Problem
+	for rel, want := range Generated(pages) {
+		got, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(rel)))
+		if err != nil || string(got) != want {
+			problems = append(problems, Problem{rel, 0, "out of date: run px1 docs manifest"})
+		}
+	}
+	return problems
+}

diff --git a/internal/docs/docs_test.go b/internal/docs/docs_test.go
new file mode 100644
index 0000000..67f2662
--- /dev/null
+++ b/internal/docs/docs_test.go
@@ -0,0 +1,223 @@
+package docs
+
+import (
+	"os"
+	"path/filepath"
+	"strings"
+	"testing"
+)
+
+const goodFront = "---\ntitle: A page\nsection: guides\nkind: narrative\nstatus: shipped\ncovers:\n  - tool.go\n  - pkg/\nverified_at:\n---\n"
+
+func write(t *testing.T, root, rel, content string) {
+	t.Helper()
+	full := filepath.Join(root, filepath.FromSlash(rel))
+	if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
+		t.Fatal(err)
+	}
+	if err := os.WriteFile(full, []byte(content), 0o644); err != nil {
+		t.Fatal(err)
+	}
+}
+
+// repo is a small repository whose documentation passes the check.
+func repo(t *testing.T) string {
+	t.Helper()
+	root := t.TempDir()
+	write(t, root, "tool.go", "package main\n")
+	write(t, root, "tool_test.go", "package main\n")
+	write(t, root, "pkg/a.go", "package pkg\n")
+	write(t, root, "docs/PAGE.md", goodFront+"\n# A page\n\nSee [the other page](OTHER.md#part) and [the site](https://example.com).\n")
+	write(t, root, "docs/OTHER.md", strings.Replace(goodFront, "covers:\n  - tool.go\n  - pkg/\n", "covers: []\n", 1)+"\n# Other\n")
+	if _, err := WriteGenerated(root); err != nil {
+		t.Fatal(err)
+	}
+	return root
+}
+
+func messages(t *testing.T, root string) string {
+	t.Helper()
+	problems, err := Check(root)
+	if err != nil {
+		t.Fatal(err)
+	}
+	var lines []string
+	for _, problem := range problems {
+		lines = append(lines, problem.String())
+	}
+	return strings.Join(lines, "\n")
+}
+
+func TestCleanRepositoryPasses(t *testing.T) {
+	if got := messages(t, repo(t)); got != "" {
+		t.Fatalf("unexpected problems:\n%s", got)
+	}
+}
+
+func TestParsePageReadsFrontMatter(t *testing.T) {
+	page, problems := parsePage("docs/PAGE.md", strings.Replace(goodFront, "verified_at:", "verified_at: 7905993", 1)+"body\n")
+	if len(problems) != 0 {
+		t.Fatalf("problems: %v", problems)
+	}
+	if page.Title != "A page" || page.Section != "guides" || page.Kind != "narrative" || page.Status != "shipped" || page.VerifiedAt != "7905993" {
+		t.Fatalf("page = %+v", page)
+	}
+	if len(page.Covers) != 2 || page.Covers[0] != "tool.go" || page.Covers[1] != "pkg/" {
+		t.Fatalf("covers = %v", page.Covers)
+	}
+	if page.body != "body\n" || page.bodyStart != 11 {
+		t.Fatalf("body = %q at line %d", page.body, page.bodyStart)
+	}
+}
+
+func TestParsePageRejectsBadFrontMatter(t *testing.T) {
+	cases := map[string]struct{ text, want string }{
+		"none":       {"# Title\n", "missing front matter"},
+		"unclosed":   {"---\ntitle: x\n", "not closed"},
+		"missing":    {strings.Replace(goodFront, "status: shipped\n", "", 1), "missing status"},
+		"bad status": {strings.Replace(goodFront, "shipped", "live", 1), `status is "live"`},
+		"bad kind":   {strings.Replace(goodFront, "narrative", "essay", 1), `kind is "essay"`},
+		"unknown":    {strings.Replace(goodFront, "status:", "owner: me\nstatus:", 1), "unknown key owner"},
+		"duplicate":  {strings.Replace(goodFront, "status:", "title: again\nstatus:", 1), "duplicate key title"},
+		"bad commit": {strings.Replace(goodFront, "verified_at:", "verified_at: yesterday", 1), "verified_at must be"},
+		"stray item": {strings.Replace(goodFront, "status: shipped\n", "status: shipped\n  - stray\n", 1), "list item outside covers"},
+		"no title":   {strings.Replace(goodFront, "title: A page", "title:", 1), "title is empty"},
+	}
+	for name, c := range cases {
+		_, problems := parsePage("docs/PAGE.md", c.text)
+		found := false
+		for _, problem := range problems {
+			found = found || strings.Contains(problem.Message, c.want)
+		}
+		if !found {
+			t.Errorf("%s: want %q in %v", name, c.want, problems)
+		}
+	}
+}
+
+func TestBrokenLinkIsReportedWithItsLine(t *testing.T) {
+	root := repo(t)
+	write(t, root, "docs/PAGE.md", goodFront+"\n# A page\n\n[gone](MISSING.md)\n\n```\n[example](ALSO_MISSING.md)\n```\n[out](../../elsewhere.md)\n")
+	got := messages(t, root)
+	if !strings.Contains(got, "docs/PAGE.md:14: broken link: MISSING.md") {
+		t.Errorf("missing broken link:\n%s", got)
+	}
+	if strings.Contains(got, "ALSO_MISSING") {
+		t.Errorf("a link inside a code fence was checked:\n%s", got)
+	}
+	if !strings.Contains(got, "link leaves the repository") {
+		t.Errorf("missing escape report:\n%s", got)
+	}
+}
+
+func TestCoversMustNameRealPaths(t *testing.T) {
+	root := repo(t)
+	front := strings.Replace(goodFront, "  - pkg/\n", "  - pkg\n  - gone.go\n  - nothing/*.go\n  - ../outside\n", 1)
+	write(t, root, "docs/PAGE.md", front+"\n# A page\n")
+	got := messages(t, root)
+	for _, want := range []string{
+		"must end in / exactly when it is a directory: pkg",
+		"does not exist: gone.go",
+		"matches nothing: nothing/*.go",
+		`"../outside" must be a path inside the repository`,
+	} {
+		if !strings.Contains(got, want) {
+			t.Errorf("want %q in:\n%s", want, got)
+		}
+	}
+}
+
+func TestNewCodeNeedsAPageOrAKnownGap(t *testing.T) {
+	root := repo(t)
+	write(t, root, "newcmd.go", "package main\n")
+	write(t, root, "internal/fresh/x.go", "package fresh\n")
+	write(t, root, "node_modules/dep/x.go", "package dep\n")
+	got := messages(t, root)
+	if !strings.Contains(got, "newcmd.go has no page") || !strings.Contains(got, "internal/fresh/ has no page") {
+		t.Fatalf("uncovered code was not reported:\n%s", got)
+	}
+	if strings.Contains(got, "node_modules") || strings.Contains(got, "tool_test.go") {
+		t.Fatalf("dependencies or tests were treated as code units:\n%s", got)
+	}
+
+	write(t, root, ConfigFile, `{"known_gaps":["newcmd.go","internal/fresh/"]}`)
+	if got := messages(t, root); got != "" {
+		t.Fatalf("known gaps still reported:\n%s", got)
+	}
+}
+
+func TestKnownGapsCannotGoStale(t *testing.T) {
+	root := repo(t)
+	write(t, root, ConfigFile, `{"known_gaps":["pkg/","removed.go"],"extra_units":["action.yml"]}`)
+	got := messages(t, root)
+	for _, want := range []string{
+		"known gap pkg/ now has a page",
+		"known gap removed.go is not a code unit any more",
+		"action.yml has no page",
+		"extra unit does not exist: action.yml",
+	} {
+		if !strings.Contains(got, want) {
+			t.Errorf("want %q in:\n%s", want, got)
+		}
+	}
+}
+
+func TestCoveredMatching(t *testing.T) {
+	cases := []struct {
+		unit, entry string
+		want        bool
+	}{
+		{"tool.go", "tool.go", true},
+		{"internal/a/", "internal/", true},
+		{"internal/a/", "internal/a/file.go", true},
+		{"eval_run.go", "eval_*.go", true},
+		{"internal/ab/", "internal/a/", false},
+		{"tool.go", "tool.go.bak", false},
+		{"internal/a/", "internal/a", false},
+	}
+	for _, c := range cases {
+		if got := covered(c.unit, c.entry); got != c.want {
+			t.Errorf("covered(%q, %q) = %v", c.unit, c.entry, got)
+		}
+	}
+}
+
+func TestStaleManifestAndIndexAreReported(t *testing.T) {
+	root := repo(t)
+	write(t, root, "docs/OTHER.md", strings.Replace(goodFront, "covers:\n  - tool.go\n  - pkg/\n", "covers: []\n", 1)+"\n# Renamed\n")
+	if got := messages(t, root); got != "" {
+		t.Fatalf("a body change must not make the manifest stale:\n%s", got)
+	}
+	write(t, root, "docs/THIRD.md", strings.Replace(goodFront, "A page", "Third", 1)+"\n# Third\n")
+	got := messages(t, root)
+	if !strings.Contains(got, "docs/manifest.json: out of date") || !strings.Contains(got, "docs/README.md: out of date") {
+		t.Fatalf("stale generated files not reported:\n%s", got)
+	}
+	changed, err := WriteGenerated(root)
+	if err != nil || len(changed) != 2 {
+		t.Fatalf("changed=%v err=%v", changed, err)
+	}
+	if again, _ := WriteGenerated(root); len(again) != 0 {
+		t.Fatalf("second write changed %v", again)
+	}
+	index, _ := os.ReadFile(filepath.Join(root, "docs", "README.md"))
+	if !strings.Contains(string(index), "- [Third](THIRD.md) (shipped)") {
+		t.Fatalf("index:\n%s", index)
+	}
+}
+
+func TestWriteGeneratedRefusesBadFrontMatter(t *testing.T) {
+	root := repo(t)
+	write(t, root, "docs/BAD.md", "# no front matter\n")
+	if _, err := WriteGenerated(root); err == nil || !strings.Contains(err.Error(), "docs/BAD.md") {
+		t.Fatalf("err = %v", err)
+	}
+}
+
+func TestConfigRejectsUnknownKeys(t *testing.T) {
+	root := repo(t)
+	write(t, root, ConfigFile, `{"extra_unit":["action.yml"]}`)
+	if _, err := Check(root); err == nil || !strings.Contains(err.Error(), "extra_unit") {
+		t.Fatalf("err = %v", err)
+	}
+}

